SELECT CASE WHEN s.sqft >= 12299 THEN 'high' WHEN s.sqft >= 3093 THEN 'mid' ELSE 'low' END AS sqft_bucket, MAX(ss.units) AS max_units FROM store_sales ss INNER JOIN stores s ON ss.store_id = s.id LEFT JOIN products p ON ss.product_id = p.id WHERE p.supplier_id IS NULL GROUP BY CASE WHEN s.sqft >= 12299 THEN 'high' WHEN s.sqft >= 3093 THEN 'mid' ELSE 'low' END ORDER BY sqft_bucket;
